        "conceptual_explanation": "When a price increase causes a substantial percentage drop in subscriber numbers (cancellations), consumers are demonstrating high price sensitivity. Because digital entertainment subscriptions are non-essential and face substitutes (YouTube, Disney+, piracy, offline media), quantity demanded responds significantly to price, demonstrating Elastic demand.",
