      "q_num": 13,
      "is_case_based": false,
      "question": "Suppose conflict escalates between the US and Iran. This conflict leads to a naval blockade in the \nStrait of Hormuz, a critical transit route through which 20% of the world's crude oil passes. At the \nsame time, widespread panic drives regular consumers and commercial airlines to stockpile fuel \nout of fear that supplies will dry up by the following week. This sudden surge in panic buying, \nhappening along with the supply disruption, creates a severe oil shortage. \n \nHow do these two events happening at the exact same time affect the global equilibrium price (P*) \nand equilibrium quantity (Q*) of crude oil?",
