        "correct_label": "B",
        "correct_text": "Inelastic demand for agricultural produce — a large increase in supply causes a proportionately larger fall in price, reducing total revenue",
        "conceptual_explanation": "The King-Davenant Law / Inelastic Demand Paradox: Agricultural staples (wheat, rice, onions) have highly inelastic consumer demand (|Ep| < 1) because people do not eat twice as much bread just because grain is cheap. When a bumper crop dramatically increases supply, price falls by a far larger percentage than the modest increase in consumption, causing total revenue (P × Q) earned by farming communities to plummet.",
