        "correct_label": "D",
        "correct_text": "Profit earned from non-regular activities, such as selling land.",
        "conceptual_explanation": "A Capital Reserve is created from capital profits generated outside the normal operating activities of a company, such as profit on the sale of fixed assets, premium on issue of shares, or revaluation surpluses. Unlike general revenue reserves, capital reserves cannot be distributed as ordinary cash dividends.",
